    var x = number;
    // ... другие инициализации ...

    let flag = false; // Объявите flag как let, чтобы можно было изменить ее значение

    function waitForFlag() {
        setTimeout(() => {
            if (flag === true) {
                // Здесь код, который нужно выполнить, когда flag станет true
                // ...
                doSomething();
            } else {
                // Если flag все еще false, повторите попытку через некоторое время
                setTimeout(waitForFlag, 100); // Повторять каждые 100 мс
            }
        }, 100); // Задержка в 100 мс
    }

    waitForFlag();

    // ... остальная часть функции ...
