        {
            PrintSolution(board);
        }
    }

    private static bool SolveNQueensUtil(int[] board, int col, int n)
    {
        if (col >= n)
        {
            return true;
        }

        for (int i = 0; i < n; i++)
        {
            if (IsSafe(board, i, col, n))
            {
                board[col] = i;

                if (SolveNQueensUtil(board, col + 1, n))
                {
                    return true;
                }

                board[col] = -1; // Backtrack
            }
        }

        return false;
    }

    private static bool IsSafe(int[] board, int row, int col, int n)
    {
        for (int i = 0; i < col; i++)
        {
            if (board[i] == row || Math.Abs(board[i] - row) == col - i)
            {
                return false;
            }
        }
        return true;
    }

    private static void PrintSolution(int[] board)
    {
        int n = board.Length;
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                if (board[i] == j)
                {
                    Console.Write("Q ");
                }
                else
                {
                    Console.Write(". ");
                }
            }
            Console.WriteLine();
        }
    }

    public static void Main(string[] args)
    {
        int n = 4; // Change this to the desired board size
        SolveNQueens(n);
    }
}
